let coffee,recipe='hoffmann',tags=[],timer,elapsed=0,stage=0,sound=true;const get=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}},bags=()=>get(K,D),brews=()=>get(B,[]),put=(k,v)=>localStorage.setItem(k,JSON.stringify(v)),esc=v=>{let e=document.createElement('span');e.textContent=v||'';return e.innerHTML},fmt=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
function view(n){$$('.view').forEach(x=>x.classList.remove('is-active'));$(`#${n}View`).classList.add('is-active');window.scrollTo({top:0,behavior:'smooth'})}function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
function shelf(){let a=bags().filter(x=>x.active);$('#coffeeShelf').innerHTML=a.map(c=>`<article class="coffee-card" data-tone="${c.tone||'ethiopia'}"><div><div class="card-top"><span>${esc(c.roaster)}</span><span>Active</span></div><h3>${esc(c.name)}</h3><p>${esc(c.origin)} · ${esc(c.process)}</p></div><div><p class="last-brew">Last brew · ${c.last.dose}g / ${c.last.water}g · ${c.last.time}<br><em>${esc(c.last.tip)}</em></p><button class="brew-again" data-brew="${c.id}">Brew again <span>→</span></button></div></article>`).join('');$$('.brew-again').forEach(x=>x.onclick=()=>prep(x.dataset.brew));$('#shelfInsight').textContent=brews().length?'Your coffee history is growing—keep changing one variable at a time.':'Start with the cup in front of you. One small adjustment is plenty.'}
function prep(id){coffee=bags().find(x=>x.id===id);let l=coffee.last;$('#prepCoffeeName').textContent=coffee.name;$('#prepCoffeeMeta').textContent=`${coffee.roaster} · ${coffee.origin} · ${coffee.process}`;$('#dose').value=l.dose;$('#water').value=l.water;$('#grindSetting').value=l.grind;$('#temperature').value=l.temp;recipeOptions();ratio();view('prep')}function recipeOptions(){$('#recipeOptions').innerHTML=R.map(x=>`<button class="recipe-option ${x.id===recipe?'selected':''}" data-r="${x.id}"><strong>${x.name}</strong><small>${x.summary}</small></button>`).join('');$$('.recipe-option').forEach(x=>x.onclick=()=>{recipe=x.dataset.r;recipeOptions()})}function ratio(){let r=parseFloat($('#water').value)/parseFloat($('#dose').value);$('#ratioValue').textContent=Number.isFinite(r)?`${r.toFixed(1)}:1`:'—';$('#ratioHint').textContent=!Number.isFinite(r)?'Enter dose and water':r<15?'Concentrated for V60—consider more water.':r>17?'Dilute for V60—consider less water.':'V60 sweet spot: 15–17:1'}const current=()=>R.find(x=>x.id===recipe);
function timeline(){$('#timeline').innerHTML=current().stages.map((_,i)=>`<span class="${i<stage?'done':i===stage?'current':''}"></span>`).join('')}function renderStage(){let s=current().stages[stage];if(!s)return end();$('#stageLabel').textContent=s[0];$('#stageTimer').textContent=fmt(s[1]);$('#stageInstruction').textContent=s[4];$('#targetWeight').textContent=`${s[2]} g`;$('#technique').textContent=s[3];timeline()}function cue(){if(!sound)return;if(navigator.vibrate)navigator.vibrate(35);try{let a=new AudioContext,o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=520;g.gain.setValueAtTime(.04,a.currentTime);o.start();o.stop(a.currentTime+.08)}catch{}}function start(){clearInterval(timer);timer=setInterval(()=>{elapsed++;let prev=current().stages.slice(0,stage).reduce((n,x)=>n+x[1],0),left=current().stages[stage][1]-(elapsed-prev);$('#elapsedTimer').textContent=fmt(elapsed);$('#stageTimer').textContent=fmt(Math.max(0,left));if(left<=0){stage++;cue();renderStage()}},1000);$('#pauseBrew').textContent='Pause'}function guided(){elapsed=0;stage=0;renderStage();view('brew');start()}function end(){clearInterval(timer);tags=[];let t=['Sour','Bitter','Balanced','Weak','Strong','Sweet','Fruity','Floral'];$('#tasteTags').innerHTML=t.map(x=>`<button data-tag="${x}">${x}</button>`).join('');$$('[data-tag]').forEach(x=>x.onclick=()=>{x.classList.toggle('selected');tags=$$('.taste-tags .selected').map(y=>y.dataset.tag)});$('#suggestedNotes').innerHTML=coffee.notes.map(x=>`<span>${x}</span>`).join('');view('taste')}
function rec(){if(tags.includes('Sour'))return['Try one notch finer','Sourness often points to a shorter extraction. Move your Timemore one small step finer and keep everything else still.','A finer grind slows the drawdown and can help bring more sweetness forward. Change one variable, then compare.'];if(tags.includes('Bitter'))return['Try one notch coarser','The cup read bitter. Try opening the grind one small step and keep your 16:1 ratio.','A coarser setting typically reduces extraction. Keeping ratio and temperature stable makes the result easier to read.'];if(tags.includes('Weak'))return['Try a 15.5:1 ratio','Keep the same 20g dose and try 310g water next time.','A slightly tighter ratio can add concentration without making the brew process more complicated.'];return['Keep this recipe close','This looks like a steady reference point. Brew it once more before changing anything.','Repeated cups tell a clearer story than a single experiment. Palate will use the comparison when you are ready to adjust.']}
function saveBrew(){let r=rec(),e={id:Date.now(),coffeeId:coffee.id,recipe,dose:$('#dose').value,water:$('#water').value,grinder:$('#grinder').value,setting:$('#grindSetting').value,temp:$('#temperature').value,tags,note:$('#tastingNote').value};put(B,[e,...brews()]);$('#savedTitle').textContent=`${coffee.name}, remembered.`;$('#savedSummary').textContent=tags.length?`You noticed ${tags.join(', ')}. Your brew settings are saved with this tasting.`:'Your brew settings are saved; a simple impression is enough to learn from.';$('#recommendationTitle').textContent=r[0];$('#recommendationCopy').textContent=r[1];$('#deepDiveCopy').textContent=r[2];view('saved')}
function add(){let d=$('#scanDialog');$('#newCoffeeName').value='';$('#newOrigin').value='';$('#newProcess').value='';$('#newNotes').value='';$('#photoPreview').removeAttribute('src');$('#photoDrop').classList.remove('has-photo');d.showModal()}function photo(e){let f=e.target.files[0];if(!f)return;let r=new FileReader;r.onload=()=>{$('#photoPreview').src=r.result;$('#photoDrop').classList.add('has-photo');if(!$('#newCoffeeName').value)$('#newCoffeeName').value=f.name.replace(/\.[^.]+$/,'').replace(/[-_]/g,' ')};r.readAsDataURL(f)}function saveCoffee(){let n=$('#newCoffeeName').value.trim();if(!n)return toast('Add the coffee name before saving.');let a=bags(),k=n.toLowerCase().replace(/[^a-z0-9]/g,''),c=a.find(x=>x.name.toLowerCase().replace(/[^a-z0-9]/g,'')===k);if(c){c.active=true;toast('This coffee is already in your history—reactivated.')}else{a.unshift({id:`coffee-${Date.now()}`,name:n,roaster:$('#newRoaster').value.trim()||'Unknown roaster',origin:$('#newOrigin').value.trim()||'Origin not yet noted',process:$('#newProcess').value.trim()||'Process not yet noted',notes:$('#newNotes').value.split(',').map(x=>x.trim()).filter(Boolean),tone:'ethiopia',active:true,last:{dose:20,water:320,grind:'7.5',temp:200,time:'—',tip:'Your first brew becomes the reference.'}});toast('Coffee added to your active shelf.')}put(K,a);$('#scanDialog').close();shelf()}
$('#addCoffee').onclick=add;$('#bagPhoto').onchange=photo;$('#saveCoffee').onclick=e=>{e.preventDefault();saveCoffee()};$('#dose').oninput=ratio;$('#water').oninput=ratio;$('#startBrew').onclick=guided;$('#dismissTip').onclick=()=>toast('Last settings kept.');$('#stopBrew').onclick=()=>{clearInterval(timer);view('prep')};$('#skipStage').onclick=()=>{stage++;cue();renderStage()};$('#pauseBrew').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('#pauseBrew').textContent='Resume'}else start()};$('#saveBrew').onclick=saveBrew;$('#deepDive').onclick=()=>$('#deepDiveCopy').classList.toggle('show');$('#soundToggle').onclick=()=>{sound=!sound;$('#soundToggle').setAttribute('aria-pressed',sound);toast(sound?'Cues on.':'Cues off.')};$$('[data-home]').forEach(x=>x.onclick=()=>{clearInterval(timer);shelf();view('shelf')});shelf();
